INSERT INTO `price` VALUES (1,'Basic 1000 sq.ft. basement','30 240','pricing_table1','Tub/shower area recessed shelf, Shower area custom built bench with halfwall, Sterling Accord seat eat Lamp wiring and installation, Wall tile installation (per sq.ft.), Additional storage cabinet, Tub/shower area recessed shelf, Shower area custom built bench with halfwall','2020-08-07 18:54:47'),(2,'Basic Bathroom','13 500','pricing_table2','Tub/shower area recessed shelf, Shower area custom built bench with halfwall, Sterling Accord seat eat Lamp wiring and installation, Wall tile installation (per sq.ft.), Additional storage cabinet, Tub/shower area recessed shelf, Shower area custom built bench with halfwall','2020-08-07 18:55:06'),(3,'Basic Wet Bar','2 500','pricing_table3','Tub/shower area recessed shelf, Shower area custom built bench with halfwall, Sterling Accord seat eat Lamp wiring and installation, Wall tile installation (per sq.ft.), Additional storage cabinet, Tub/shower area recessed shelf, Shower area custom built bench with halfwall','2020-08-07 18:55:19');
